using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Collections.Generic;
using Autodesk.AutoCAD.DatabaseServices;
using Autodesk.AutoCAD.Geometry;
using Autodesk.AutoCAD.Colors;
using Autodesk.AutoCAD.Runtime;
using MedGas2024.Core;
using MedGas2024.Engine;
[assembly:CommandClass(typeof(LegacyMapRuntimeTests1952))]
public static class LegacyMapRuntimeTests1952
{
    static readonly List<string> log=new List<string>();static void Check(bool c,string m){if(!c)throw new System.Exception(m);log.Add("PASS: "+m);}
    static bool Reject(Action a){try{a();return false;}catch(InvalidOperationException){return true;}catch(ArgumentException){return true;}}
    static ObjectId Type(Database db,ObjectId style,string name,string text,bool u=false){using(var tr=db.TransactionManager.StartTransaction()){var table=(LinetypeTable)tr.GetObject(db.LinetypeTableId,OpenMode.ForWrite);var t=new LinetypeTableRecord{Name=name,Comments="source "+text,NumDashes=3,PatternLength=70};table.Add(t);tr.AddNewlyCreatedDBObject(t,true);t.SetDashLengthAt(0,40);t.SetDashLengthAt(1,-15);t.SetDashLengthAt(2,-15);t.SetShapeStyleAt(1,style);t.SetShapeScaleAt(1,2.5);t.SetTextAt(1,text);t.SetShapeOffsetAt(1,new Vector2d(-6,-1));t.SetShapeIsUcsOrientedAt(1,u);t.SetShapeRotationAt(1,0);tr.Commit();return t.ObjectId;}}
    static ObjectId Layer(Database db,string name,ObjectId type,bool locked=false){using(var tr=db.TransactionManager.StartTransaction()){var table=(LayerTable)tr.GetObject(db.LayerTableId,OpenMode.ForWrite);var layer=new LayerTableRecord{Name=name,LinetypeObjectId=type,Color=Color.FromColorIndex(ColorMethod.ByAci,3),IsLocked=locked};table.Add(layer);tr.AddNewlyCreatedDBObject(layer,true);tr.Commit();return layer.ObjectId;}}
    static ObjectId Pipe(Database db,ObjectId layer,ObjectId type,double scale){using(var tr=db.TransactionManager.StartTransaction()){var bt=(BlockTable)tr.GetObject(db.BlockTableId,OpenMode.ForRead);var space=(BlockTableRecord)tr.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForWrite);var p=new Polyline();p.AddVertexAt(0,new Point2d(10,20),0,3,3);p.AddVertexAt(1,new Point2d(210,20),0,3,3);space.AppendEntity(p);tr.AddNewlyCreatedDBObject(p,true);p.LayerId=layer;p.LinetypeId=type;p.LinetypeScale=scale;p.Color=Color.FromRgb(10,20,30);tr.Commit();return p.ObjectId;}}
    static ObjectId Style(Database db){using(var tr=db.TransactionManager.StartTransaction()){var styles=(TextStyleTable)tr.GetObject(db.TextStyleTableId,OpenMode.ForWrite);var st=new TextStyleTableRecord{Name="MAP_TEST",FileName="arial.ttf",TextSize=0,XScale=1};styles.Add(st);tr.AddNewlyCreatedDBObject(st,true);tr.Commit();return st.ObjectId;}}
    static void Mark(Database db,string text){var c=LabelService.Read(db);var edit=new LabelEdit{ForceR=true,Recenter=false};var plan=LabelService.Inspect(db,new LabelScope{Keys=new[]{LabelRules.Key(text,false)},Fingerprint=c.Fingerprint},edit);LabelService.Apply(db,plan,edit);}
    static bool HasType(Database db,string name){using(var tr=db.TransactionManager.StartOpenCloseTransaction())return ((LinetypeTable)tr.GetObject(db.LinetypeTableId,OpenMode.ForRead)).Has(name);}
    static void TestNew(Database db)
    {
        var style=Style(db);var source=Type(db,style,"Mr.T_R0_0123456789abcdef","VAC.D15");var oldLayer=Layer(db,"OLD_LAYER",db.ContinuousLinetype);var targetLayer=Layer(db,"Mr.T_VAC_D15_RAW",db.ContinuousLinetype);var one=Pipe(db,oldLayer,source,.25);var two=Pipe(db,oldLayer,source,.5);var other=Pipe(db,targetLayer,db.ByLayerLinetype,1);Mark(db,"VAC.D15");var cat=LegacyMapping.Read(db);var row=cat.Rows.Single(r=>r.Source=="Mr.T_R0_0123456789abcdef");Check(row.Count==2&&String.IsNullOrEmpty(row.TargetType),"Unresolved legacy row is listed with label and actual direct object count");row.Use=true;row.TargetLayer="Mr.T_VAC_D15_RAW";row.TargetType="Mr.T_VAC_D15_RAW";row.SyncLayer=true;var plan=LegacyMapping.Inspect(db,cat.Rows,cat.Fingerprint);Check(plan.Actions.Count==1&&plan.Actions[0].Create&&plan.Actions[0].Objects.Count==2&&plan.Preview[0].Detail.Contains("ảnh hưởng thêm 1"),"Preview describes a new named R type, destination Layer and other ByLayer references");Check(!HasType(db,row.TargetType),"Preview is read-only");Check(Reject(()=>LegacyMapping.Apply(db,cat.Rows,plan,true))&&!HasType(db,row.TargetType),"Injected failure rolls back the new linetype and assignments");using(var tr=db.TransactionManager.StartOpenCloseTransaction()){Check(((Entity)tr.GetObject(one,OpenMode.ForRead)).LayerId==oldLayer&&((LayerTableRecord)tr.GetObject(targetLayer,OpenMode.ForRead)).LinetypeObjectId==db.ContinuousLinetype,"Rollback preserves source and Layer linetype");}
        int count=LegacyMapping.Apply(db,cat.Rows,plan);Check(count==2&&HasType(db,row.TargetType),"Explicit mapping creates readable linetype and updates both selected source curves");using(var tr=db.TransactionManager.StartOpenCloseTransaction()){var lt=(LinetypeTable)tr.GetObject(db.LinetypeTableId,OpenMode.ForRead);var type=lt[row.TargetType];var entity=(Polyline)tr.GetObject(one,OpenMode.ForRead);Check(entity.LayerId==targetLayer&&entity.LinetypeId==db.ByLayerLinetype&&((LayerTableRecord)tr.GetObject(targetLayer,OpenMode.ForRead)).LinetypeObjectId==type,"Destination Layer and its linetype agree and pipe uses ByLayer");Check(entity.LinetypeScale==.25&&entity.ConstantWidth==3&&entity.GetPoint2dAt(0)==new Point2d(10,20)&&entity.Color.Red==10,"Mapping preserves geometry, width, scale and color");var newType=(LinetypeTableRecord)tr.GetObject(type,OpenMode.ForRead);Check(newType.TextAt(1)=="VAC.D15"&&!newType.ShapeIsUcsOrientedAt(1)&&Math.Abs(newType.ShapeRotationAt(1))<1e-10,"New definition retains source text and R=0");Check(((Entity)tr.GetObject(other,OpenMode.ForRead)).LinetypeId==db.ByLayerLinetype,"Other ByLayer entity remains ByLayer while Layer type changes");}
    }
    static void TestExisting(Database db)
    {
        var style=Style(db);var source=Type(db,style,"Mr.T_R0_1111111111111111","Oxy.D12");var target=Type(db,style,"Mr.T_OXY_D12_RAW","D12.Oxy",true);var mismatch=Type(db,style,"Mr.T_CO2_D12_RAW","D12.CO2");var oldLayer=Layer(db,"OLD_SOURCE",db.ContinuousLinetype);var dest=Layer(db,"Mr.T_OXY_D12_RAW",target);var p=Pipe(db,oldLayer,source,.3);var other=Pipe(db,dest,db.ByLayerLinetype,1);Mark(db,"Oxy.D12");var cat=LegacyMapping.Read(db);var row=cat.Rows.Single();row.Use=true;row.TargetLayer="Mr.T_OXY_D12_RAW";row.TargetType="Mr.T_OXY_D12_RAW";Check(Reject(()=>LegacyMapping.Inspect(db,cat.Rows,cat.Fingerprint)),"Existing U linetype cannot silently replace source R");row.CopySourceToExisting=true;var plan=LegacyMapping.Inspect(db,cat.Rows,cat.Fingerprint);Check(plan.Preview[0].Detail.Contains("GHI ĐÈ")&&plan.Preview[0].Detail.Contains("đối tượng tham chiếu"),"Explicit R overwrite warns about shared target references");using(var tr=db.TransactionManager.StartTransaction()){((Entity)tr.GetObject(other,OpenMode.ForWrite)).LinetypeId=mismatch;tr.Commit();}Check(Reject(()=>LegacyMapping.Apply(db,cat.Rows,plan)),"Changed drawing state prevents stale reviewed apply");using(var tr=db.TransactionManager.StartTransaction()){((Entity)tr.GetObject(other,OpenMode.ForWrite)).LinetypeId=db.ByLayerLinetype;tr.Commit();}cat=LegacyMapping.Read(db);row=cat.Rows.Single();row.Use=true;row.TargetLayer="Mr.T_OXY_D12_RAW";row.TargetType="Mr.T_CO2_D12_RAW";row.CopySourceToExisting=true;Check(Reject(()=>LegacyMapping.Inspect(db,cat.Rows,cat.Fingerprint)),"Different target text is rejected even when copy is requested");row.TargetType="Mr.T_OXY_D12_RAW";plan=LegacyMapping.Inspect(db,cat.Rows,cat.Fingerprint);LegacyMapping.Apply(db,cat.Rows,plan);using(var tr=db.TransactionManager.StartOpenCloseTransaction()){var t=(LinetypeTableRecord)tr.GetObject(target,OpenMode.ForRead);var e=(Entity)tr.GetObject(p,OpenMode.ForRead);Check(t.TextAt(1)=="Oxy.D12"&&!t.ShapeIsUcsOrientedAt(1)&&e.LayerId==dest&&e.LinetypeId==db.ByLayerLinetype,"Explicit overwrite updates existing target to source R and matches Layer");}
    }
    [CommandMethod("MRTMAPTEST1952",CommandFlags.Modal)]public static void Run()
    {
        log.Clear();var previous=HostApplicationServices.WorkingDatabase;string root=Directory.GetParent(Path.GetDirectoryName(Assembly.GetExecutingAssembly().Location)).FullName;
        try{using(var db=new Database(true,true)){HostApplicationServices.WorkingDatabase=db;TestNew(db);}using(var db=new Database(true,true)){HostApplicationServices.WorkingDatabase=db;TestExisting(db);}log.Add("RESULT: PASS; scratch database only; interactive GUI and plotting are separate.");}
        catch(System.Exception ex){log.Add("RESULT: FAIL");log.Add(ex.ToString());}finally{HostApplicationServices.WorkingDatabase=previous;File.WriteAllLines(Path.Combine(root,"evidence","legacy-map-runtime-1952.txt"),log);var doc=Autodesk.AutoCAD.ApplicationServices.Core.Application.DocumentManager.MdiActiveDocument;if(doc!=null)doc.Editor.WriteMessage("\n"+String.Join("\n",log)+"\n");}
    }
}

